CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;


DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260602233556_InitialCreate') THEN
    CREATE TABLE "Users" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" character varying(120) NOT NULL,
        "Email" character varying(160) NOT NULL,
        "Role" character varying(40) NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_Users" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260602233556_InitialCreate') THEN
    CREATE TABLE "Farms" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" character varying(120) NOT NULL,
        "OwnerName" character varying(120) NOT NULL,
        "City" character varying(80) NOT NULL,
        "State" character varying(2) NOT NULL,
        "TotalArea" numeric(12,2) NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        "UserId" integer,
        CONSTRAINT "PK_Farms" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Farms_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE SET NULL
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260602233556_InitialCreate') THEN
    CREATE TABLE "CropAreas" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" character varying(120) NOT NULL,
        "CropType" character varying(80) NOT NULL,
        "AreaSize" numeric(12,2) NOT NULL,
        "Latitude" numeric(10,6) NOT NULL,
        "Longitude" numeric(10,6) NOT NULL,
        "Status" integer NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        "FarmId" integer NOT NULL,
        CONSTRAINT "PK_CropAreas" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_CropAreas_Farms_FarmId" FOREIGN KEY ("FarmId") REFERENCES "Farms" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260602233556_InitialCreate') THEN
    CREATE TABLE "ClimateAlerts" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "AlertType" character varying(60) NOT NULL,
        "Severity" integer NOT NULL,
        "Title" character varying(160) NOT NULL,
        "Description" character varying(500) NOT NULL,
        "Status" integer NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        "ResolvedAt" timestamp with time zone,
        "CropAreaId" integer NOT NULL,
        CONSTRAINT "PK_ClimateAlerts" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_ClimateAlerts_CropAreas_CropAreaId" FOREIGN KEY ("CropAreaId") REFERENCES "CropAreas" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260602233556_InitialCreate') THEN
    CREATE TABLE "SatelliteData" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Source" character varying(80) NOT NULL,
        "NdviAverage" numeric(5,2) NOT NULL,
        "NdviMin" numeric(5,2) NOT NULL,
        "NdviMax" numeric(5,2) NOT NULL,
        "SurfaceTemperature" numeric(6,2) NOT NULL,
        "CloudCoverage" numeric(5,2) NOT NULL,
        "FireFocusNearby" boolean NOT NULL,
        "FireFocusDistanceKm" numeric(8,2),
        "CaptureDate" date NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        "CropAreaId" integer NOT NULL,
        CONSTRAINT "PK_SatelliteData" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_SatelliteData_CropAreas_CropAreaId" FOREIGN KEY ("CropAreaId") REFERENCES "CropAreas" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260602233556_InitialCreate') THEN
    CREATE TABLE "Sensors" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" character varying(120) NOT NULL,
        "SensorType" character varying(60) NOT NULL,
        "Status" character varying(30) NOT NULL,
        "InstallationDate" timestamp with time zone NOT NULL,
        "CropAreaId" integer NOT NULL,
        CONSTRAINT "PK_Sensors" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Sensors_CropAreas_CropAreaId" FOREIGN KEY ("CropAreaId") REFERENCES "CropAreas" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260602233556_InitialCreate') THEN
    CREATE TABLE "Recommendations" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Message" character varying(500) NOT NULL,
        "Priority" character varying(30) NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        "ClimateAlertId" integer NOT NULL,
        CONSTRAINT "PK_Recommendations" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Recommendations_ClimateAlerts_ClimateAlertId" FOREIGN KEY ("ClimateAlertId") REFERENCES "ClimateAlerts" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260602233556_InitialCreate') THEN
    CREATE TABLE "SensorReadings" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Temperature" numeric(6,2) NOT NULL,
        "AirHumidity" numeric(5,2) NOT NULL,
        "SoilHumidity" numeric(5,2) NOT NULL,
        "ManualAlert" boolean NOT NULL,
        "ReadingDate" timestamp with time zone NOT NULL,
        "SensorId" integer NOT NULL,
        CONSTRAINT "PK_SensorReadings" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_SensorReadings_Sensors_SensorId" FOREIGN KEY ("SensorId") REFERENCES "Sensors" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

