DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261108162725_SecurityAndIdempotency') THEN
    ALTER TABLE "Users" ADD "PasswordHash" text NOT NULL DEFAULT '';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261108162725_SecurityAndIdempotency') THEN
    CREATE TABLE "IdempotencyRecords" (
        "Key" character varying(64) NOT NULL,
        "RequestHash" text NOT NULL,
        "StatusCode" integer NOT NULL,
        "Body" text NOT NULL,
        "ContentType" text NOT NULL,
        "Location" text,
        "CreatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_IdempotencyRecords" PRIMARY KEY ("Key")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261108162725_SecurityAndIdempotency') THEN
    CREATE UNIQUE INDEX "IX_Users_Email" ON "Users" ("Email");
